import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] planned = new long[n];
        for (int i = 0; i < n; i++) planned[i] = nextLong();
        // Both dates are below 2^30: sort (planned, alternate) packed into one long.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = (planned[i] << 30) | nextLong();
        Arrays.sort(key);
        // In planned order, use the alternate date when it is not earlier than the current day.
        long day = 0, mask = (1L << 30) - 1;
        for (long k : key) {
            long alt = k & mask;
            day = alt >= day ? alt : k >>> 30;
        }
        System.out.println(day);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	planned := make([]int64, n)
	for i := range planned {
		planned[i] = nextInt()
	}
	// Both dates are below 2^30: sort (planned, alternate) packed into one int64.
	key := make([]int64, n)
	for i := range key {
		key[i] = planned[i]<<30 | nextInt()
	}
	slices.Sort(key)
	// In planned order, use the alternate date when it is not earlier than the current day.
	day := int64(0)
	for _, k := range key {
		if alt := k & (1<<30 - 1); alt >= day {
			day = alt
		} else {
			day = k >> 30
		}
	}
	fmt.Println(day)
}
